/**
 * A* pathfinding on a 2D grid with 4-connected movement.
 * Cells are addressed as "x,y" strings; a blocked set can change over time,
 * so the caller decides which obstacles exist at the moment of planning.
 */

export interface Pos {
  x: number;
  y: number;
}

export const key = (p: Pos): string => `${p.x},${p.y}`;

export class Grid {
  constructor(
    public readonly width: number,
    public readonly height: number,
    public readonly walls: Set<string> = new Set(),
  ) {}

  inBounds(p: Pos): boolean {
    return p.x >= 0 && p.x < this.width && p.y >= 0 && p.y < this.height;
  }

  isWall(p: Pos): boolean {
    return this.walls.has(key(p));
  }

  /** A cell may be entered only if it is in bounds and not a wall *now*. */
  passable(p: Pos): boolean {
    return this.inBounds(p) && !this.isWall(p);
  }
}

const DIRS: Pos[] = [
  { x: 1, y: 0 },
  { x: -1, y: 0 },
  { x: 0, y: 1 },
  { x: 0, y: -1 },
];

const manhattan = (a: Pos, b: Pos): number =>
  Math.abs(a.x - b.x) + Math.abs(a.y - b.y);

/** Minimal binary heap keyed by numeric priority. */
class MinHeap<T> {
  private items: { prio: number; val: T }[] = [];

  get size(): number {
    return this.items.length;
  }

  push(prio: number, val: T): void {
    const a = this.items;
    a.push({ prio, val });
    let i = a.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (a[parent]!.prio <= a[i]!.prio) break;
      [a[i], a[parent]] = [a[parent]!, a[i]!];
      i = parent;
    }
  }

  pop(): T | undefined {
    const a = this.items;
    if (a.length === 0) return undefined;
    const top = a[0];
    const last = a.pop()!;
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < a.length && a[l]!.prio < a[m]!.prio) m = l;
        if (r < a.length && a[r]!.prio < a[m]!.prio) m = r;
        if (m === i) break;
        [a[i], a[m]] = [a[m]!, a[i]!];
        i = m;
      }
    }
    return top.val;
  }
}

/**
 * Compute a shortest path from start to goal avoiding the given walls.
 * Returns the closed list of cells including both endpoints, or null when
 * no route exists.
 */
export function astar(grid: Grid, start: Pos, goal: Pos): Pos[] | null {
  if (!grid.passable(start) || !grid.passable(goal)) return null;

  const gScore = new Map<string, number>([[key(start), 0]]);
  const cameFrom = new Map<string, string>();
  const open = new MinHeap<Pos>();
  open.push(manhattan(start, goal), start);
  const closed = new Set<string>();

  while (open.size > 0) {
    const current = open.pop()!;
    const ck = key(current);
    if (closed.has(ck)) continue; // stale heap entry
    if (current.x === goal.x && current.y === goal.y) {
      // Reconstruct.
      const path: Pos[] = [];
      let k: string | undefined = ck;
      while (k !== undefined) {
        const [xs, ys] = k.split(",");
        path.push({ x: Number(xs), y: Number(ys) });
        k = cameFrom.get(k);
      }
      return path.reverse();
    }
    closed.add(ck);

    const gc = gScore.get(ck)!;
    for (const d of DIRS) {
      const next: Pos = { x: current.x + d.x, y: current.y + d.y };
      if (!grid.passable(next)) continue;
      const nk = key(next);
      if (closed.has(nk)) continue;
      const tentative = gc + 1;
      if (tentative < (gScore.get(nk) ?? Infinity)) {
        gScore.set(nk, tentative);
        cameFrom.set(nk, ck);
        open.push(tentative + manhattan(next, goal), next);
      }
    }
  }
  return null;
}

