/**
 * Agent simulation with dynamic replanning:
 *
 * - A 15x15 open grid. The agent plans (0,0) -> (14,14) with A*.
 * - It executes the plan one step per tick.
 * - After 5 executed steps, a wall segment appears covering the next 3 cells
 *   of its remaining path (the world changes mid-route).
 * - The agent detects the collision ahead, replans from its current position
 *   against the walls that exist at that tick, and continues to the goal.
 *
 * Every decision is recorded in an event log for verification.
 */

import { astar, Grid, key, type Pos } from "./astar.js";

export const GRID_SIZE = 15;
export const START: Pos = { x: 0, y: 0 };
export const GOAL: Pos = { x: GRID_SIZE - 1, y: GRID_SIZE - 1 };
export const STEPS_BEFORE_WALL = 5;
export const WALL_LENGTH = 3;

export type EventType = "plan" | "move" | "wall-added" | "replan" | "arrive";

export interface Event {
  tick: number;
  type: EventType;
  /** For move/replan/arrive: where the agent is or is heading. */
  pos?: Pos;
  /** For wall-added / replan. */
  detail?: string;
}

export interface WallAppearance {
  /** First tick at which this wall exists and must be respected. */
  tick: number;
  cells: Pos[];
}

export interface SimulationResult {
  reachedGoal: boolean;
  /** Cells actually visited by the agent, starting at START. */
  executedPath: Pos[];
  events: Event[];
  /** Wall timeline: walls exist on every tick >= their appearance tick. */
  wallAppearances: WallAppearance[];
  finalTick: number;
}

/** Walls that exist at a given tick (appearance tick inclusive). */
export function wallsAtTick(
  appearances: WallAppearance[],
  tick: number,
): Set<string> {
  const s = new Set<string>();
  for (const app of appearances) {
    if (app.tick <= tick) for (const c of app.cells) s.add(key(c));
  }
  return s;
}

export function runSimulation(): SimulationResult {
  const events: Event[] = [];
  const wallAppearances: WallAppearance[] = [];
  const executedPath: Pos[] = [{ ...START }];

  // --- Initial plan -------------------------------------------------------
  let grid = new Grid(GRID_SIZE, GRID_SIZE, new Set());
  let plan = astar(grid, START, GOAL);
  if (!plan) throw new Error("no initial route on an open grid");
  events.push({ tick: 0, type: "plan", pos: { ...START }, detail: "initial" });

  let cursor = 0; // index of the agent's position within `plan`
  let tick = 0;
  let replanned = false;

  while (tick < 10_000) {
    const pos = plan[cursor]!;
    if (pos.x === GOAL.x && pos.y === GOAL.y) {
      events.push({ tick, type: "arrive", pos: { ...pos } });
      return {
        reachedGoal: true,
        executedPath,
        events,
        wallAppearances,
        finalTick: tick,
      };
    }

    // --- Mid-route world change -------------------------------------------
    if (
      !replanned &&
      executedPath.length - 1 === STEPS_BEFORE_WALL && // exactly 5 steps done
      cursor + WALL_LENGTH < plan.length
    ) {
      // Wall covers the next 3 cells of the remaining path.
      const blocked = plan.slice(cursor + 1, cursor + 1 + WALL_LENGTH).map((p) => ({ ...p }));
      wallAppearances.push({ tick, cells: blocked });
      events.push({
        tick,
        type: "wall-added",
        detail: blocked.map(key).join(" "),
      });

      // Replan from the current position against the walls that exist NOW.
      grid = new Grid(GRID_SIZE, GRID_SIZE, wallsAtTick(wallAppearances, tick));
      const detour = astar(grid, pos, GOAL);
      if (!detour) throw new Error("walled in with no alternative route");
      plan = detour;
      cursor = 0;
      replanned = true;
      events.push({
        tick,
        type: "replan",
        pos: { ...pos },
        detail: `${plan.length - 1} steps to goal`,
      });
      continue; // re-evaluate from the same position under the new plan
    }

    // --- Execute one step, validating against walls as they exist now ------
    const next = plan[cursor + 1];
    if (!next) throw new Error("ran out of plan before reaching the goal");
    if (!grid.passable(next)) {
      throw new Error(`agent tried to enter wall ${key(next)} at tick ${tick}`);
    }
    tick += 1;
    cursor += 1;
    executedPath.push({ ...next });
    events.push({ tick, type: "move", pos: { ...next } });
  }

  return {
    reachedGoal: false,
    executedPath,
    events,
    wallAppearances,
    finalTick: tick,
  };
}

