import { describe, expect, it } from "vitest";
import { astar, Grid, key, type Pos } from "../src/astar.js";
import {
  GRID_SIZE,
  GOAL,
  START,
  STEPS_BEFORE_WALL,
  WALL_LENGTH,
  runSimulation,
  wallsAtTick,
} from "../src/agent.js";

const manhattan = (a: Pos, b: Pos): number =>
  Math.abs(a.x - b.x) + Math.abs(a.y - b.y);

/** Optimal length on the open 15x15 grid: 28 steps (29 cells). */
const optimal = astar(
  new Grid(GRID_SIZE, GRID_SIZE),
  START,
  GOAL,
)!.length - 1;

describe("dynamic replanning with A*", () => {
  const sim = runSimulation();

  it("plans the initial route optimally on an open grid", () => {
    const open = new Grid(GRID_SIZE, GRID_SIZE);
    const path = astar(open, START, GOAL);
    expect(path).not.toBeNull();
    expect(path!.length - 1).toBe(2 * (GRID_SIZE - 1));
    expect(optimal).toBe(28);
  });

  it("the agent still reaches the goal", () => {
    expect(sim.reachedGoal).toBe(true);
    const last = sim.executedPath[sim.executedPath.length - 1]!;
    expect(last).toEqual(GOAL);
  });

  it("a wall segment appears mid-route covering the next 3 cells", () => {
    expect(sim.wallAppearances).toHaveLength(1);
    const app = sim.wallAppearances[0]!;
    // Exactly 5 steps were executed before the wall appeared.
    expect(app.tick).toBe(STEPS_BEFORE_WALL);
    expect(app.cells).toHaveLength(WALL_LENGTH);
    // The wall lies strictly ahead of the agent's position at that tick.
    const posAtWall = sim.executedPath[STEPS_BEFORE_WALL]!;
    for (const c of app.cells) {
      expect(c).not.toEqual(posAtWall);
      expect(manhattan(posAtWall, c)).toBeGreaterThan(0);
    }
  });

  it("the executed path is valid against walls as they exist per tick", () => {
    const path = sim.executedPath;
    // Starts at START.
    expect(path[0]).toEqual(START);

    let prev = path[0]!;
    for (let step = 1; step < path.length; step++) {
      const cur = path[step]!;

      // In bounds.
      expect(cur.x).toBeGreaterThanOrEqual(0);
      expect(cur.x).toBeLessThan(GRID_SIZE);
      expect(cur.y).toBeGreaterThanOrEqual(0);
      expect(cur.y).toBeLessThan(GRID_SIZE);

      // One 4-connected step per move.
      expect(manhattan(prev, cur)).toBe(1);

      // Never enters a wall — checked at the tick this move happens.
      const walls = wallsAtTick(sim.wallAppearances, step);
      expect(walls.has(key(cur))).toBe(false);

      prev = cur;
    }

    // Sanity: the wall really does block the original remaining path cells,
    // i.e. the obstacle is real and was respected.
    const app = sim.wallAppearances[0]!;
    const walls = wallsAtTick(sim.wallAppearances, app.tick + 1);
    for (const c of app.cells) expect(walls.has(key(c))).toBe(true);
  });

  it("executed length is within [optimal, optimal + 10]", () => {
    const executedSteps = sim.executedPath.length - 1;
    expect(optimal).toBe(28);
    expect(executedSteps).toBeGreaterThanOrEqual(optimal);
    expect(executedSteps).toBeLessThanOrEqual(optimal + 10);
  });

  it("the event log records exactly one replan", () => {
    const replans = sim.events.filter((e) => e.type === "replan");
    expect(replans).toHaveLength(1);

    // And the replan happens after the wall appears, from the agent's position.
    const wallEventIndex = sim.events.findIndex((e) => e.type === "wall-added");
    const replanIndex = sim.events.indexOf(replans[0]!);
    expect(replanIndex).toBe(wallEventIndex + 1);
    expect(replans[0]!.pos).toEqual(sim.executedPath[STEPS_BEFORE_WALL]);

    // The log also contains exactly one initial plan and one arrival.
    expect(sim.events.filter((e) => e.type === "plan")).toHaveLength(1);
    expect(sim.events.filter((e) => e.type === "arrive")).toHaveLength(1);

    // Every logged move matches a consecutive cell of the executed path.
    const moves = sim.events.filter((e) => e.type === "move");
    expect(moves).toHaveLength(sim.executedPath.length - 1);
    moves.forEach((e, i) => {
      expect(e.pos).toEqual(sim.executedPath[i + 1]);
      expect(e.tick).toBe(i + 1);
    });
  });
});

